    "p": 63,
    "t": "Les unités spécialisées : la SCP, section commando parachutiste du 2e REP. Le groupe commando montagne du 2e REG. Les plongeurs de combat du génie et le DINOPS. Et les sections de tireurs d'élite, la STE, au 2e REP, au 2e REI et à la 13e DBLE.",
