    "p": 149,
    "t": "Neuvième leçon : le tir. D'abord, la sécurité. Une arme ne tire pas toute seule : il faut une action du doigt sur la détente. Ce sont les mauvaises manipulations qui provoquent les accidents. Il y a quatre règles, sans exception. Un : une arme doit toujours être considérée comme chargée. Deux : ne jamais pointer le canon d'une arme sur quelque chose que l'on ne veut pas détruire. Trois : garder l'index hors de la détente tant que les organes de visée ne sont pas sur l'objectif. Quatre : être sûr de son objectif et de son environnement.",
